-- ----------------------------------------------------------------------------
-- SetRules: The twelve structural rules of the theory: the eleven classical naive rules plus the missing Rule 12.
-- ----------------------------------------------------------------------------
INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-1', 1, 'Membership', 'A set is a collection of distinct objects; x in S asserts x is a member of S.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-2', 2, 'Extensionality', 'A set is fully determined by its members; sets with the same membership profile are identical.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-3', 3, 'Order-independence', 'The order in which members are listed carries no information.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-4', 4, 'Repetition-independence', 'Listing a member more than once adds nothing.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-5', 5, 'Two descriptions', 'A set may be given by enumeration or by a membership condition phi.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-6', 6, 'Comprehension', 'Any condition you can state determines a set of exactly the objects satisfying it.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-7', 7, 'Unbounded size', 'A set may have any number of members: none, finitely many, or infinitely many.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-8', 8, 'Empty set', 'There is a set with no members.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-9', 9, 'Singletons', 'For any object there is a one-member set, distinct from that member.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-10', 10, 'Nesting', 'Sets may be members of other sets.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-11', 11, 'Self-membership', 'A set may be a member of itself; S in S is a well-formed question.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

INSERT INTO set_rules (set_rule_id, rule_number, title, statement)
VALUES ('rule-12', 12, 'NULL membership', 'If a set''s condition loops back on itself with no stable True/False value, x in S = NULL.') ON CONFLICT (set_rule_id) DO UPDATE SET rule_number = EXCLUDED.rule_number, title = EXCLUDED.title, statement = EXCLUDED.statement;

